SINA_SMART["immuno1-dynamics"] = {"lecture":"immuno1-dynamics","title":"Dynamics of the immune response","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"immuno1-dynamics:e0","text":"Adaptive: one receptor per lymphocyte → clonal expansion → effector + memory cells.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-dynamics:e1","text":"Phases: initiation (APC-T), expansion (Th-B, Th-T), effector (Th1, Th2, CTL).","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-dynamics:e2","text":"Co-signals: membrane co-stimulation and cytokines/chemokines.","topic":"Cooperation and activation","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-dynamics:e3","text":"CD4 ↔ MHC II; CD8 ↔ MHC I; B cells see intact antigen.","topic":"Cooperation and activation","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-dynamics:e4","text":"Signal 1 (TCR-MHC), signal 2 (co-stimulation), signal 3 (cytokines, polarisation).","topic":"Cooperation and activation","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-dynamics:e5","text":"Early events: phosphorylation; late: NF-κB, NFAT transcription.","topic":"Cooperation and activation","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-dynamics:e6","text":"Th1 (IL-12 → IL-2, IFN-γ): cellular. Th2 (IL-4, 5, 10, 13): humoral.","topic":"Th1 and Th2 polarisation","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-dynamics:e7","text":"T-independent antigens: IgM, no switch, low affinity, no memory.","topic":"B-cell responses","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-dynamics:e8","text":"T-dependent: MHC II presentation by B cell, CD40L-CD40, class switching, memory.","topic":"B-cell responses","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-dynamics:e9","text":"Class switching: same specificity, different Fc.","topic":"B-cell responses","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"4m2m4x":"a","ntkd2k":"a","b5t5ba":"a","yliacq":"a","17i70zk":"a","1m56klf":"a","53gvqi":"a","11xe2v1":"a","bbcri3":"a","1we4kv2":"a","1tbj376":"a","11fw4sl":"a"},"mapCounts":{"verified":0,"auto":12,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"immuno1-dynamics:e0":{"s":0,"u":["Adaptive: one receptor per lymphocyte → clonal expansion → effector + memory cells.","The adaptive immune response adapts to the aggressor: each lymphocyte carries a single receptor of unique specificity; high-affinity binding to its antigen triggers clonal expansion , then differentiation into effector and memory cells.","It unfolds in secondary lymphoid organs through cellular cooperation in three phases: initiation (APC-T cooperation), clonal expansion (Th-B and Th-T cooperation) and effector phase (Th1, Th2, cytotoxic T lymphocytes)."],"dp":[]},"immuno1-dynamics:e1":{"s":0,"u":["Phases: initiation (APC-T), expansion (Th-B, Th-T), effector (Th1, Th2, CTL).","It unfolds in secondary lymphoid organs through cellular cooperation in three phases: initiation (APC-T cooperation), clonal expansion (Th-B and Th-T cooperation) and effector phase (Th1, Th2, cytotoxic T lymphocytes)."],"dp":[]},"immuno1-dynamics:e2":{"s":1,"u":["Co-signals: membrane co-stimulation and cytokines/chemokines.","Cells cooperate through membrane co-signals (co-stimulatory molecules) and soluble co-signals (cytokines, chemokines for migration), which allow, amplify and control the response.","Activation of a CD4 T cell needs signal 1 (TCR + peptide-MHC II) and signal 2 (co-stimulation); signal 3 (cytokines) polarises the response."],"dp":[]},"immuno1-dynamics:e3":{"s":1,"u":["CD4 ↔ MHC II; CD8 ↔ MHC I; B cells see intact antigen.","CD4 T cells recognise antigen with MHC class II , CD8 T cells with MHC class I ; B cells recognise intact antigen.","Activation of a CD4 T cell needs signal 1 (TCR + peptide-MHC II) and signal 2 (co-stimulation); signal 3 (cytokines) polarises the response."],"dp":[]},"immuno1-dynamics:e4":{"s":1,"u":["Signal 1 (TCR-MHC), signal 2 (co-stimulation), signal 3 (cytokines, polarisation).","Activation of a CD4 T cell needs signal 1 (TCR + peptide-MHC II) and signal 2 (co-stimulation); signal 3 (cytokines) polarises the response.","Cells cooperate through membrane co-signals (co-stimulatory molecules) and soluble co-signals (cytokines, chemokines for migration), which allow, amplify and control the response."],"dp":[]},"immuno1-dynamics:e5":{"s":1,"u":["Early events: phosphorylation; late: NF-κB, NFAT transcription.","Molecular events: early (seconds-minutes: phosphorylation cascades downstream of the receptor) and late (gene transcription via transcription factors such as NF-κB and NFAT )."],"dp":[]},"immuno1-dynamics:e6":{"s":2,"u":["Th1 (IL-12 → IL-2, IFN-γ): cellular. Th2 (IL-4, 5, 10, 13): humoral.","Naive Th0 cells become Th1 under IL-12 , secreting IL-2 and IFN-γ : cellular immunity against intracellular pathogens (viruses, some bacteria and parasites); or Th2 , secreting IL-4, IL-5, IL-10, IL-13 : humoral immunity against extracellular pathogens."],"dp":[]},"immuno1-dynamics:e7":{"s":3,"u":["T-independent antigens: IgM, no switch, low affinity, no memory.","T-independent antigens (polysaccharides such as LPS, polymeric proteins such as flagellin) cross-link many BCRs through repeated epitopes: mainly IgM , no class switching , low affinity , no memory .","T-dependent antigens (proteins): the B cell internalises antigen bound to surface IgM, degrades it and presents peptides on MHC class II to a helper T cell, which responds via CD40L-CD40 and cytokines, driving activation, differentiation and isotype (class) switching : heavy-chain constant gene rearrangement giving the same specificity (Fv) with different effector properties (Fc) , plus affinity maturation and memory."],"dp":[{"h":"Why polysaccharide vaccines are conjugated","t":"Capsular polysaccharides (pneumococcus, Haemophilus, meningococcus) are T-independent antigens: they give short-lived IgM without memory and work poorly in infants. Coupling them to a protein carrier turns the response T-dependent, because B cells now present carrier peptides to helper T cells. The result is class switching, high-affinity IgG and memory, which is why conjugate vaccines protect babies. Source: the lecture's T-dependent vs T-independent antigens."}]},"immuno1-dynamics:e8":{"s":3,"u":["T-dependent: MHC II presentation by B cell, CD40L-CD40, class switching, memory.","T-dependent antigens (proteins): the B cell internalises antigen bound to surface IgM, degrades it and presents peptides on MHC class II to a helper T cell, which responds via CD40L-CD40 and cytokines, driving activation, differentiation and isotype (class) switching : heavy-chain constant gene rearrangement giving the same specificity (Fv) with different effector properties (Fc) , plus affinity maturation and memory.","Humoral immunity (B cells becoming antibody-secreting plasma cells) is T-dependent or T-independent depending on the antigen."],"dp":[]},"immuno1-dynamics:e9":{"s":3,"u":["Class switching: same specificity, different Fc.","T-dependent antigens (proteins): the B cell internalises antigen bound to surface IgM, degrades it and presents peptides on MHC class II to a helper T cell, which responds via CD40L-CD40 and cytokines, driving activation, differentiation and isotype (class) switching : heavy-chain constant gene rearrangement giving the same specificity (Fv) with different effector properties (Fc) , plus affinity maturation and memory.","T-independent antigens (polysaccharides such as LPS, polymeric proteins such as flagellin) cross-link many BCRs through repeated epitopes: mainly IgM , no class switching , low affinity , no memory ."],"dp":[]}},"meta":{"4m2m4x":{"a":"recall","vg":"immuno1-dynamics:e0/recall/1"},"ntkd2k":{"a":"recall","vg":"immuno1-dynamics:e0/recall/2"},"b5t5ba":{"a":"recall","vg":"immuno1-dynamics:e3/recall/1"},"yliacq":{"a":"recall","vg":"immuno1-dynamics:e4/recall/1"},"17i70zk":{"a":"recall","vg":"immuno1-dynamics:e5/recall/1"},"1m56klf":{"a":"recall","vg":"immuno1-dynamics:e1/recall/1"},"53gvqi":{"a":"recall","vg":"immuno1-dynamics:e6/recall/1"},"11xe2v1":{"a":"recall","vg":"immuno1-dynamics:e6/recall/2"},"bbcri3":{"a":"recall","vg":"immuno1-dynamics:e7/recall/1"},"1we4kv2":{"a":"recall","vg":"immuno1-dynamics:e7/recall/2"},"1tbj376":{"a":"recall","vg":"immuno1-dynamics:e8/recall/1"},"11fw4sl":{"a":"recall","vg":"immuno1-dynamics:e9/recall/1"}},"explRev":"e30ad11b388c"};
